using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Backend.Models.Enums;

namespace Backend.Models;

public class AiRecommendation
{
    public Guid Id { get; set; } = Guid.NewGuid();

    public Guid ReviewId { get; set; }
    [JsonIgnore]
    public PerformanceReview? Review { get; set; }

    public Guid EmployeeId { get; set; }
    public User? Employee { get; set; }

    public AiRecommendationStatus Status { get; set; } = AiRecommendationStatus.Pending;

    /// <summary>
    /// Executive summary generated by AI or edited by manager.
    /// </summary>
    public string? Summary { get; set; }

    /// <summary>
    /// JSON array of key employee strengths identified by AI.
    /// </summary>
    public string? StrengthsJson { get; set; }

    /// <summary>
    /// JSON array of areas for growth and improvement identified by AI.
    /// </summary>
    public string? ImprovementAreasJson { get; set; }

    /// <summary>
    /// JSON array of actionable recommendations with success measures and timeframes.
    /// Format: [{ "description": string, "successMeasure": string, "timeframe": string }]
    /// </summary>
    public string? ActionItemsJson { get; set; }

    /// <summary>
    /// JSON array of suggested training topics / professional development courses.
    /// </summary>
    public string? TrainingTopicsJson { get; set; }

    /// <summary>
    /// Complete raw JSON string returned by Groq LLM before manager modifications.
    /// </summary>
    public string? RawResponseJson { get; set; }

    /// <summary>
    /// Manual notes or justification entered by manager (required on ManualOverride).
    /// </summary>
    [MaxLength(2000)]
    public string? ManualNotes { get; set; }

    public Guid? ReviewedById { get; set; }
    public User? ReviewedBy { get; set; }

    public DateTime? ReviewedAt { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}

